import pytest
from candidate import monotonic


class TestMonotonic:
    def test_increasing_list_returns_true(self):
        assert monotonic([1, 2, 4, 20]) is True

    def test_decreasing_list_returns_true(self):
        assert monotonic([4, 1, 0, -10]) is True

    def test_non_monotonic_list_returns_false(self):
        assert monotonic([1, 20, 4, 10]) is False

    def test_empty_list_returns_true(self):
        assert monotonic([]) is True

    def test_single_element_list_returns_true(self):
        assert monotonic([42]) is True

    def test_two_elements_increasing(self):
        assert monotonic([1, 2]) is True

    def test_two_elements_decreasing(self):
        assert monotonic([2, 1]) is True

    def test_two_elements_equal(self):
        assert monotonic([5, 5]) is True

    def test_all_elements_equal_returns_true(self):
        assert monotonic([7, 7, 7, 7, 7]) is True

    def test_duplicates_in_increasing_order(self):
        assert monotonic([1, 1, 2, 2, 3]) is True

    def test_duplicates_in_decreasing_order(self):
        assert monotonic([5, 4, 4, 3, 3, 2]) is True

    def test_mixed_duplicates_not_monotonic(self):
        assert monotonic([1, 3, 2, 2, 4]) is False

    def test_negative_numbers_increasing(self):
        assert monotonic([-10, -5, -1, 0, 5]) is True

    def test_negative_numbers_decreasing(self):
        assert monotonic([5, 0, -1, -5, -10]) is True

    def test_floats_increasing(self):
        assert monotonic([1.1, 2.2, 3.3, 4.4]) is True

    def test_floats_decreasing(self):
        assert monotonic([4.4, 3.3, 2.2, 1.1]) is True

    def test_floats_not_monotonic(self):
        assert monotonic([1.1, 3.3, 2.2, 4.4]) is False

    def test_mixed_int_and_float_increasing(self):
        assert monotonic([1, 2.5, 3, 4.5, 5]) is True

    def test_mixed_int_and_float_not_monotonic(self):
        assert monotonic([1, 3.5, 2, 4]) is False

    def test_large_increasing_list(self):
        assert monotonic(list(range(1000))) is True

    def test_large_decreasing_list(self):
        assert monotonic(list(range(1000, 0, -1))) is True

    def test_large_not_monotonic_list(self):
        assert monotonic([1, 3, 2, 4, 3, 5]) is False

    def test_zero_in_list(self):
        assert monotonic([0, 0, 0]) is True

    def test_none_input_raises_type_error(self):
        with pytest.raises(TypeError):
            monotonic(None)

    def test_string_input_returns_false(self):
        assert monotonic("abc") is False

    def test_tuple_input_returns_false(self):
        assert monotonic((1, 2, 3)) is False

    def test_integer_input_raises_type_error(self):
        with pytest.raises(TypeError):
            monotonic(123)

    def test_bool_list_increasing(self):
        assert monotonic([False, True]) is True

    def test_bool_list_decreasing(self):
        assert monotonic([True, False]) is True

    def test_bool_list_not_monotonic(self):
        assert monotonic([True, False, True]) is False

    def test_very_large_numbers(self):
        assert monotonic([10**18, 10**18 + 1, 10**18 + 2]) is True

    def test_very_small_numbers_decreasing(self):
        assert monotonic([10**18 + 2, 10**18 + 1, 10**18]) is True

    def test_alternating_sequence_not_monotonic(self):
        assert monotonic([1, -1, 1, -1, 1]) is False

    def test_peak_sequence_not_monotonic(self):
        assert monotonic([1, 2, 3, 2, 1]) is False

    def test_valley_sequence_not_monotonic(self):
        assert monotonic([3, 2, 1, 2, 3]) is False
